INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind AGB immer gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwillig, aber üblich"}, {"text": "Ja", "correct": false, "because": "Keine Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit AGB?', 3, '[{"text": "Rechtssicherheit schaffen", "correct": true, "because": "Regelt Vertragsdetails"}, {"text": "Kundengewinnung", "correct": false, "because": "Nicht primär"}, {"text": "Produktbeschreibung", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören typischerweise in AGB?', 5, '[{"text": "Zahlungsbedingungen", "correct": true, "because": "Regelt Finanzen"}, {"text": "Lieferfristen", "correct": true, "because": "Definiert Leistung"}, {"text": "Mitarbeiterdaten", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AGB müssen klar formuliert sein. b) Sie gelten automatisch ohne Zustimmung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zustimmung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung von AGB?', 4, '[{"text": "Gesetzliche Vorgaben", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Kundenverständnis", "correct": false, "because": "Klarheit wichtig"}, {"text": "Firmenfarben", "correct": true, "because": "Irrelevant für Inhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob AGB individuell angepasst werden können?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel gestaltbar"}, {"text": "Nein", "correct": false, "because": "Anpassung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelung ist in AGB oft enthalten?', 3, '[{"text": "Widerrufsrecht", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Produktpreise", "correct": false, "because": "Eher im Vertrag"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Interner Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur rechtlichen Wirkung von AGB?', 5, '[{"text": "Vertragsteilnahme", "correct": true, "because": "Wird bei Zustimmung bindend"}, {"text": "Kundenschutz", "correct": true, "because": "Regelt Rechte"}, {"text": "Produktwerbung", "correct": false, "because": "Kein rechtlicher Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) AGB dürfen Kunden nicht benachteiligen. b) Sie sind immer einseitig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einseitigkeit nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei AGB unwichtig?', 4, '[{"text": "Rechtskonformität", "correct": false, "because": "Pflicht"}, {"text": "Verständlichkeit", "correct": false, "because": "Vermeidet Streit"}, {"text": "Design der Webseite", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen AGB dem Kunden vorliegen?', 2, '[{"text": "Ja", "correct": true, "because": "Vor Vertragsabschluss nötig"}, {"text": "Nein", "correct": false, "because": "Pflicht zur Einsicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen AGB?', 4, '[{"text": "Rechtliche Absicherung", "correct": true, "because": "Schützt Unternehmen"}, {"text": "Standardisierung", "correct": true, "because": "Vereinfacht Prozesse"}, {"text": "Höhere Umsätze", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass AGB automatisch gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Zustimmung erforderlich"}, {"text": "Ja", "correct": false, "because": "Nicht ohne Akzeptanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gestaltung von AGB?', 3, '[{"text": "Klarheit", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Länge", "correct": false, "because": "Sekundär"}, {"text": "Marketing", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AGB regeln Haftung. b) Sie ersetzen Verträge.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben schlecht formulierte AGB?', 5, '[{"text": "Rechtsstreitigkeiten", "correct": true, "because": "Unklarheit führt zu Konflikten"}, {"text": "Kundenverlust", "correct": true, "because": "Misstrauen entsteht"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei AGB unwichtig?', 3, '[{"text": "Gesetzliche Grenzen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Kundenrechte", "correct": false, "because": "Pflicht"}, {"text": "Firmenhistorie", "correct": true, "because": "Kein Vertragsbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können AGB geändert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Ankündigung möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob AGB auch online gelten?', 2, '[{"text": "Ja", "correct": true, "because": "Für Webshops üblich"}, {"text": "Nein", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelung wähle ich für Rücksendungen?', 4, '[{"text": "Fristen und Kosten", "correct": true, "because": "Klarheit für Kunden"}, {"text": "Produktbeschreibung", "correct": false, "because": "Anderer Bereich"}, {"text": "Mitarbeiteranzahl", "correct": false, "because": "Irrelevant"}]');
